"""Unit tests for //third_party/protobuf/check_file_lists.py."""

import io
import json
import os
import posixpath
import sys
import tempfile
import unittest
from unittest import mock

_PROTOBUF_DIRECTORY = os.path.dirname(os.path.abspath(__file__))
if _PROTOBUF_DIRECTORY not in sys.path:
    sys.path.insert(0, _PROTOBUF_DIRECTORY)

import check_file_lists


class CheckFileListsTest(unittest.TestCase):
    """Proves CMake/GN parsing and release diff invariants for protobuf."""

    def testParseCmakeFileListsExtractsSourceDirRelativePathsPerTarget(self):
        cmake_text = (
            '# Auto-generated by @//pkg:gen_src_file_lists_cmake\n'
            'set(libprotobuf_lite_srcs\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/any_lite.cc\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/arena.cc\n'
            ')\n'
            '\n'
            'set(libprotoc_hdrs\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/compiler/plugin.h\n'
            ')\n'
        )

        parsed_lists = check_file_lists.ParseCmakeFileLists(cmake_text)

        self.assertEqual(
            {
                'libprotobuf_lite_srcs': {
                    'src/google/protobuf/any_lite.cc',
                    'src/google/protobuf/arena.cc',
                },
                'libprotoc_hdrs': {
                    'src/google/protobuf/compiler/plugin.h',
                },
            },
            parsed_lists,
            msg=(
                'Expected ParseCmakeFileLists to strip the '
                '${protobuf_SOURCE_DIR}/ prefix from each set(...) block.'),
        )

    def testParseCmakeFileListsMergesRepeatedSetBlocksForSameTarget(self):
        cmake_text = (
            'set(protoc\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/compiler/main.cc\n'
            ')\n'
            'set(protoc\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/compiler/extra.cc\n'
            ')\n'
        )

        parsed_lists = check_file_lists.ParseCmakeFileLists(cmake_text)

        self.assertEqual(
            {
                'src/google/protobuf/compiler/main.cc',
                'src/google/protobuf/compiler/extra.cc',
            },
            parsed_lists['protoc'],
            msg=(
                'Expected repeated set(protoc ...) blocks in file_lists.cmake '
                'to merge rather than overwrite earlier entries.'),
        )

    def testParseCmakeFileListsHandlesEmptySetBlockWithoutSwallowingNextTarget(
            self):
        cmake_text = (
            '# count=0\n'
            'set(conformance_testee_hdrs\n'
            ')\n'
            '\n'
            'set(conformance_testee_srcs\n'
            '  ${protobuf_SOURCE_DIR}/conformance/conformance_cpp.cc\n'
            ')\n'
        )

        parsed_lists = check_file_lists.ParseCmakeFileLists(cmake_text)

        self.assertEqual(
            {
                'conformance_testee_hdrs': set(),
                'conformance_testee_srcs': {
                    'conformance/conformance_cpp.cc',
                },
            },
            parsed_lists,
            msg=(
                'Expected an empty set(...) block to close at its own '
                'parenthesis without swallowing the following set(...) block.'),
        )

    def testParseGnSourceFilesExpandsChainedPathVariablesInOrder(self):
        proto_sources_gni = (
            '_include_dir = "src/google/protobuf"\n'
            '_cpp_dir = "$_include_dir/compiler/cpp"\n'
            '_cpp_dir_internal = "$_cpp_dir/field_generators"\n'
            '_java_dir = "java/core/src/main/java/com/google/protobuf/"\n'
            '_python_dir = "python/google/protobuf"\n'
            'protobuf_headers = [\n'
            '  "$_include_dir/message.h",\n'
            '  "$_include_dir/port_def.inc",\n'
            ']\n'
            'protoc_cpp_sources = [\n'
            '  "$_cpp_dir/enum.cc",\n'
            '  "$_cpp_dir_internal/cord_field.cc",\n'
            ']\n'
            'javaproto_sources = [\n'
            '  "$_java_dir/ByteString.java",\n'
            ']\n'
            'pyproto_sources = [\n'
            '  "$_python_dir/descriptor.py",\n'
            ']\n'
        )
        build_gn = (
            'executable("protoc") {\n'
            '  sources = [ "src/google/protobuf/compiler/main.cc" ]\n'
            '}\n'
            'source_set("utf8_range") {\n'
            '  sources = [ "third_party/utf8_range/utf8_range.c" ]\n'
            '}\n'
        )

        parsed_files = check_file_lists.ParseGnSourceFiles(
            [proto_sources_gni, build_gn])

        self.assertEqual(
            {
                'src/google/protobuf/message.h',
                'src/google/protobuf/port_def.inc',
                'src/google/protobuf/compiler/cpp/enum.cc',
                ('src/google/protobuf/compiler/cpp/field_generators/'
                 'cord_field.cc'),
                'java/core/src/main/java/com/google/protobuf/ByteString.java',
                'python/google/protobuf/descriptor.py',
                'src/google/protobuf/compiler/main.cc',
                'third_party/utf8_range/utf8_range.c',
            },
            parsed_files,
            msg=(
                'Expected ParseGnSourceFiles to expand chained and '
                'prefix-overlapping GN path variables (_include_dir -> '
                '_cpp_dir -> _cpp_dir_internal) and normalize slashes.'),
        )

    def testParseGnSourceFilesMatchesQuotesWithinSingleLineOnly(self):
        gn_text = (
            'protobuf_lite_sources = [\n'
            '  "src/google/protobuf/arena.cc",\n'
            '  "src/google/protobuf/map.cc",\n'
            ']\n'
        )

        parsed_files = check_file_lists.ParseGnSourceFiles([gn_text])

        self.assertEqual(
            {
                'src/google/protobuf/arena.cc',
                'src/google/protobuf/map.cc',
            },
            parsed_files,
            msg=(
                'Expected quote matching to stay within single lines so '
                'adjacent entries are never skipped.'),
        )

    def testParseGnSourceFilesIgnoresCommentsTemplatesAndProtoFiles(self):
        gn_text = (
            '# "src/google/protobuf/commented_out.cc"\n'
            'outputs = [ "$proto_python_root/{{source_file_part}}" ]\n'
            'sources = [\n'
            '  "src/google/protobuf/any.proto",\n'
            '  "src/google/protobuf/any.cc",\n'
            ']\n'
        )

        parsed_files = check_file_lists.ParseGnSourceFiles([gn_text])

        self.assertEqual(
            {'src/google/protobuf/any.cc'},
            parsed_files,
            msg=(
                'Expected comments, unresolved GN templates, and .proto '
                'schema files to be excluded from parsed source files.'),
        )

    def testRealCheckedInProtobufGnFilesPopulateExpectedSourceDirectories(self):
        chromium_gn_files = check_file_lists.ReadChromiumGnSourceFiles(
            _PROTOBUF_DIRECTORY)
        directories_with_files = {
            posixpath.dirname(path) for path in chromium_gn_files
        }
        expected_directories = {
            'src/google/protobuf',
            'src/google/protobuf/compiler',
            'src/google/protobuf/compiler/cpp',
            'src/google/protobuf/compiler/java/full',
            'src/google/protobuf/compiler/python',
            'java/core/src/main/java/com/google/protobuf',
            'python/google/protobuf',
        }

        self.assertTrue(
            expected_directories.issubset(directories_with_files),
            msg=(
                f'Expected real GN files to populate {expected_directories}, '
                f'but only found {directories_with_files}.'),
        )

    def testRealCheckedInProtobufFilesProduceCleanSelfDiff(self):
        cmake_path = os.path.join(
            _PROTOBUF_DIRECTORY, 'src', 'file_lists.cmake')
        with open(cmake_path, 'r', encoding='utf-8') as cmake_file:
            cmake_text = cmake_file.read()
        chromium_gn_files = check_file_lists.ReadChromiumGnSourceFiles(
            _PROTOBUF_DIRECTORY)

        diff = check_file_lists.ComputeFileListsDiff(
            old_cmake_text=cmake_text,
            new_cmake_text=cmake_text,
            chromium_gn_files=chromium_gn_files,
            new_tree_directory=_PROTOBUF_DIRECTORY,
        )

        self.assertFalse(
            diff.HasUnfollowedChanges(),
            msg=(
                'Expected diffing the checked-in src/file_lists.cmake against '
                f'itself to report no changes, but got {diff}.'),
        )

    def testComputeFileListsDiffReportsAddedUpstreamFilesWithSiblingCounts(
            self):
        old_cmake_text = (
            'set(libprotobuf_lite_srcs\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/arena.cc\n'
            ')\n'
        )
        new_cmake_text = (
            'set(libprotobuf_lite_srcs\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/arena.cc\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/offset_ptr.cc\n'
            ')\n'
            'set(libprotobuf_srcs\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/offset_ptr.cc\n'
            ')\n'
            'set(libprotoc_srcs\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/compiler/'
            'csharp/new.cc\n'
            ')\n'
        )
        chromium_gn_files = {
            'src/google/protobuf/arena.cc',
            'src/google/protobuf/arena.h',
            'src/google/protobuf/message.h',
        }

        diff = check_file_lists.ComputeFileListsDiff(
            old_cmake_text=old_cmake_text,
            new_cmake_text=new_cmake_text,
            chromium_gn_files=chromium_gn_files,
        )

        self.assertEqual(
            (
                check_file_lists.AddedUpstreamFile(
                    path='src/google/protobuf/compiler/csharp/new.cc',
                    upstream_lists=('libprotoc_srcs',),
                    chromium_sibling_count=0,
                ),
                check_file_lists.AddedUpstreamFile(
                    path='src/google/protobuf/offset_ptr.cc',
                    upstream_lists=(
                        'libprotobuf_lite_srcs',
                        'libprotobuf_srcs',
                    ),
                    chromium_sibling_count=3,
                ),
            ),
            diff.added_files,
            msg=(
                'Expected newly added upstream files to record their CMake '
                'lists and the count of Chromium-built sibling files.'),
        )

    def testComputeFileListsDiffExcludesAddedFilesAlreadyListedInChromiumGn(
            self):
        old_cmake_text = (
            'set(libprotobuf_srcs\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/arena.cc\n'
            ')\n'
        )
        new_cmake_text = (
            'set(libprotobuf_srcs\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/arena.cc\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/symbol.cc\n'
            ')\n'
        )
        chromium_gn_files = {
            'src/google/protobuf/arena.cc',
            'src/google/protobuf/symbol.cc',
        }

        diff = check_file_lists.ComputeFileListsDiff(
            old_cmake_text=old_cmake_text,
            new_cmake_text=new_cmake_text,
            chromium_gn_files=chromium_gn_files,
        )

        self.assertEqual(
            (),
            diff.added_files,
            msg=(
                'Expected an added upstream file that has already been added '
                'to proto_sources.gni to be omitted from added_files.'),
        )

    def testComputeFileListsDiffReportsFilesRemovedFromUpstreamCmakeLists(
            self):
        old_cmake_text = (
            'set(libprotobuf_srcs\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/arena.cc\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/obsolete.cc\n'
            ')\n'
        )
        new_cmake_text = (
            'set(libprotobuf_srcs\n'
            '  ${protobuf_SOURCE_DIR}/src/google/protobuf/arena.cc\n'
            ')\n'
        )
        chromium_gn_files = {
            'src/google/protobuf/arena.cc',
            'src/google/protobuf/obsolete.cc',
        }

        diff = check_file_lists.ComputeFileListsDiff(
            old_cmake_text=old_cmake_text,
            new_cmake_text=new_cmake_text,
            chromium_gn_files=chromium_gn_files,
        )

        self.assertEqual(
            ('src/google/protobuf/obsolete.cc',),
            diff.removed_files,
            msg=(
                'Expected a file removed from upstream CMake lists that is '
                'still present in Chromium GN lists to appear in '
                'removed_files.'),
        )

    def testComputeFileListsDiffReportsGnFilesMissingFromNewUpstreamTree(self):
        with tempfile.TemporaryDirectory() as temporary_directory:
            existing_file = os.path.join(
                temporary_directory, 'src', 'google', 'protobuf', 'arena.cc')
            os.makedirs(os.path.dirname(existing_file), exist_ok=True)
            with open(existing_file, 'w', encoding='utf-8') as file_handle:
                file_handle.write('// arena.cc\n')

            chromium_gn_files = {
                'src/google/protobuf/arena.cc',
                'java/core/src/main/java/com/google/protobuf/BinaryReader.java',
            }

            diff = check_file_lists.ComputeFileListsDiff(
                old_cmake_text='',
                new_cmake_text='',
                chromium_gn_files=chromium_gn_files,
                new_tree_directory=temporary_directory,
            )

        self.assertEqual(
            ('java/core/src/main/java/com/google/protobuf/BinaryReader.java',),
            diff.removed_files,
            msg=(
                'Expected a Java source listed in proto_sources.gni that no '
                'longer exists on disk in the new tree to be reported.'),
        )

    def testComputeFileListsDiffIgnoresBootstrapFilesMissingBeforeStepFour(
            self):
        with tempfile.TemporaryDirectory() as temporary_directory:
            chromium_gn_files = {
                'python/google/protobuf/descriptor_pb2.py',
                'python/google/protobuf/compiler/plugin_pb2.py',
                'python/google/protobuf/internal/python_edition_defaults.py',
                'src/google/protobuf/descriptor.pb.cc',
                'src/google/protobuf/descriptor.pb.h',
                'src/google/protobuf/compiler/plugin.pb.cc',
                'src/google/protobuf/compiler/plugin.pb.h',
            }

            diff = check_file_lists.ComputeFileListsDiff(
                old_cmake_text='',
                new_cmake_text='',
                chromium_gn_files=chromium_gn_files,
                new_tree_directory=temporary_directory,
            )

        self.assertEqual(
            (),
            diff.removed_files,
            msg=(
                'Expected bootstrap files generated in roll step 4 by '
                'gen_extra_chromium_files.py not to be flagged as removed '
                'when checking a raw upstream tree after step 1.'),
        )

    def testFormatFileListsDiffReportDescribesCleanStateWhenNothingChanged(
            self):
        empty_diff = check_file_lists.FileListsDiff(
            added_files=(),
            removed_files=(),
        )

        report = check_file_lists.FormatFileListsDiffReport(empty_diff)

        self.assertIn(
            'No unfollowed upstream file additions or removals',
            report,
            msg='Expected clean diff report to state that no changes remain.',
        )

    def testFormatFileListsDiffReportIncludesAddedFileListsAndSiblingCount(
            self):
        diff = check_file_lists.FileListsDiff(
            added_files=(
                check_file_lists.AddedUpstreamFile(
                    path='src/google/protobuf/offset_ptr.cc',
                    upstream_lists=('libprotobuf_lite_srcs',),
                    chromium_sibling_count=121,
                ),
            ),
            removed_files=(),
        )

        report = check_file_lists.FormatFileListsDiffReport(diff)

        self.assertIn(
            '+ src/google/protobuf/offset_ptr.cc [libprotobuf_lite_srcs] '
            '(siblings in Chromium GN: 121)',
            report,
            msg=(
                'Expected report to format added file, list, and sibling '
                'count.'),
        )

    def testFormatFileListsDiffReportIncludesRemovedFilePaths(self):
        diff = check_file_lists.FileListsDiff(
            added_files=(),
            removed_files=('src/google/protobuf/obsolete.cc',),
        )

        report = check_file_lists.FormatFileListsDiffReport(diff)

        self.assertIn(
            '- src/google/protobuf/obsolete.cc',
            report,
            msg='Expected report to format removed file paths with a - prefix.',
        )

    def testCommandLineInterfaceOutputsJsonReportForExplicitFiles(self):
        with tempfile.TemporaryDirectory() as temporary_directory:
            protobuf_directory = os.path.join(temporary_directory, 'protobuf')
            os.makedirs(
                os.path.join(protobuf_directory, 'src'), exist_ok=True)

            old_cmake_path = os.path.join(temporary_directory, 'old.cmake')
            with open(old_cmake_path, 'w', encoding='utf-8') as file_handle:
                file_handle.write(
                    'set(libprotobuf_srcs\n'
                    '  ${protobuf_SOURCE_DIR}/src/old.cc\n'
                    ')\n')

            new_cmake_path = os.path.join(
                protobuf_directory, 'src', 'file_lists.cmake')
            with open(new_cmake_path, 'w', encoding='utf-8') as file_handle:
                file_handle.write(
                    'set(libprotobuf_srcs\n'
                    '  ${protobuf_SOURCE_DIR}/src/new.cc\n'
                    ')\n')

            with open(
                    os.path.join(protobuf_directory, 'proto_sources.gni'),
                    'w',
                    encoding='utf-8') as file_handle:
                file_handle.write('protobuf_sources = [ "src/old.cc" ]\n')
            with open(
                    os.path.join(protobuf_directory, 'BUILD.gn'),
                    'w',
                    encoding='utf-8') as file_handle:
                file_handle.write('# empty\n')

            stdout_buffer = io.StringIO()
            with mock.patch('sys.stdout', stdout_buffer):
                check_file_lists.main([
                    '--protobuf-dir',
                    protobuf_directory,
                    '--old-cmake',
                    old_cmake_path,
                    '--new-cmake',
                    new_cmake_path,
                    '--json',
                ])
            serialized = json.loads(stdout_buffer.getvalue())

        self.assertEqual(
            {
                'added_files': [{
                    'path': 'src/new.cc',
                    'upstream_lists': ['libprotobuf_srcs'],
                    'chromium_sibling_count': 1,
                }],
                'removed_files': ['src/old.cc'],
            },
            serialized,
            msg=(
                'Expected CLI --json output to include added and removed '
                'files.'),
        )


if __name__ == '__main__':
    unittest.main()
